template:
enum List {
    Cons(i32, ⟦tail_ty⟧),
    Nil,
}

use List::{Cons, Nil};

fn sum(list: &List) -> i32 {
    match list {
        Cons(value, tail) => value + sum(tail),
        Nil => 0,
    }
}

fn main() {
    let list = Cons(1, Box::new(Cons(2, Box::new(Nil))));
    println!("{}", sum(&list));
}

tests:
#[test]
fn sums() {
    let list = Cons(1, Box::new(Cons(2, Box::new(Nil))));
    assert_eq!(sum(&list), 3);
}
